-- name: platform__workers_completeintegrationinvocation_select_integration_invocations_organization_id_ref :one
SELECT i.id::text,i.run_id::text,r.root_run_id::text,r.project_id::text,p.ref,n.ref,i.effect_fence_digest,i.generation,i.state,i.lease_ref,i.lease_expires_at FROM control_plane.integration_invocations i JOIN control_plane.runs r ON r.id=i.run_id JOIN control_plane.projects p ON p.id=r.project_id JOIN control_plane.run_nodes n ON n.id=i.node_id WHERE i.organization_id=$1::uuid AND i.ref=$2 FOR UPDATE
